#include "vpu/api.h"
#include <stdlib.h>
#include <string.h>
void vpu_config_default(vpu_config_t*c){if(!c)return;c->memory_size=VPU_DEFAULT_MEMORY_SIZE;c->cache_lines=VPU_DEFAULT_CACHE_LINES;c->queue_capacity=VPU_DEFAULT_QUEUE_CAPACITY;c->core_count=1;}
vpu_status_t vpu_init(vpu_t*v,const vpu_config_t*cfg){if(!v)return VPU_ERR_NULL;vpu_config_t d;if(!cfg){vpu_config_default(&d);cfg=&d;}if(!cfg->core_count)return VPU_ERR_INVALID;memset(v,0,sizeof(*v));v->config=*cfg;v->cores=calloc(cfg->core_count,sizeof(*v->cores));if(!v->cores)return VPU_ERR_NOMEM;for(unsigned i=0;i<cfg->core_count;i++){vpu_status_t s=vpu_core_init(&v->cores[i],i,cfg->memory_size,cfg->cache_lines);if(s){for(unsigned j=0;j<i;j++)vpu_core_destroy(&v->cores[j]);free(v->cores);v->cores=NULL;return s;}}vpu_status_t s=vpu_scheduler_init(&v->scheduler,cfg->queue_capacity,cfg->core_count);if(s){vpu_shutdown(v);return s;}return VPU_OK;}
void vpu_shutdown(vpu_t*v){if(!v)return;if(v->cores){for(unsigned i=0;i<v->config.core_count;i++)vpu_core_destroy(&v->cores[i]);free(v->cores);v->cores=NULL;}vpu_scheduler_destroy(&v->scheduler);memset(&v->config,0,sizeof(v->config));}
const char*vpu_status_string(vpu_status_t s){switch(s){case VPU_OK:return "ok";case VPU_ERR_NULL:return "null pointer";case VPU_ERR_NOMEM:return "out of memory";case VPU_ERR_BOUNDS:return "out of bounds";case VPU_ERR_INVALID:return "invalid argument";case VPU_ERR_DIVZERO:return "division by zero";case VPU_ERR_OVERFLOW:return "overflow";case VPU_ERR_EMPTY:return "queue empty";case VPU_ERR_FULL:return "queue full";case VPU_ERR_HALTED:return "core halted";case VPU_ERR_DECODE:return "decode error";case VPU_ERR_IO:return "I/O error";default:return "unknown error";}}
vpu_status_t vpu_core_get(vpu_t*v,unsigned id,vpu_core_t**out){if(!v||!out)return VPU_ERR_NULL;if(id>=v->config.core_count)return VPU_ERR_INVALID;*out=&v->cores[id];return VPU_OK;}
